#include <iostream>
class Job {
    int size_, done_ = 0, candidate_ = 0;
    bool cancelled_ = false;

  public:
    explicit Job(int n) : size_(n) {}
    void cancel() {
        if (done_ < size_) {
            cancelled_ = true;
        }
    }
    void step() {
        if (cancelled_) {
            return;
        }
        int budget = 3;
        while (budget-- > 0 && done_ < size_) {
            ++done_;
            candidate_ += done_;
        }
    }
    bool finished() const { return done_ == size_; }
    bool cancelled() const { return cancelled_; }
    int done() const { return done_; }
    int result() const { return finished() ? candidate_ : 0; }
};
int main() {
    Job job(8);
    job.step();
    job.cancel();
    job.cancel();
    job.step();
    std::cout << job.cancelled() << ' ' << job.done() << ' ' << job.result()
              << '\n';
    Job empty(0);
    empty.cancel();
    empty.step();
    std::cout << empty.finished() << ' ' << empty.cancelled() << ' '
